mapper.select:
select id, name, type, sort, status, remark, create_by, create_time, update_by, update_time
from voya_ai_tag

    del_flag = '0'

        and type = #{type}


        and name like concat('%', #{name}, '%')


        and status = #{status}


        and create_time >= #{beginCreateTime}


        and create_time < date_add(#{endCreateTime}, interval 1 day)


order by sort desc, id desc

select count(*) from voya_ai_tag
where type = #{type} and name = #{name}
and id != #{excludeId}
